      const writeArtifactTool = tool(
        {
          name: 'write_artifact',
          description:
            'Creates or updates a named artifact in the session. ' +
            'If an artifact with the same name already exists, it will be ' +
            'replaced. Use this to produce files, reports, code, or other ' +
            'deliverables.',
